$upcoming=db()->prepare("SELECT a.*,s.name salon_name,sv.name service_name FROM appointments a JOIN salons s ON s.id=a.salon_id JOIN services sv ON sv.id=a.service_id WHERE a.customer_id=? AND a.appointment_date>=CURDATE() AND a.status NOT IN ('cancelled','rejected') ORDER BY a.appointment_date,a.start_time LIMIT 1"); $upcoming->execute([current_user()['id']]); $next=$upcoming->fetch(); $count=db()->prepare('SELECT COUNT(*) FROM appointments WHERE customer_id=?'); $count->execute([current_user()['id']]); $total=$count->fetchColumn(); $page_title='Customer dashboard'; include __DIR__.'/../includes/header.php';
